CREATE TRIGGER RefAirline_Version_Create
	ON RefAirline
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RM_PK, 'RM'
	FROM inserted
GO
CREATE TRIGGER RefAirline_Version_Update
	ON RefAirline
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RM_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefAirline_DataChangeHistory
	ON RefAirline
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RM_PK, 'RM' FROM inserted
	UNION
	SELECT RM_PK, 'RM' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefAirline_DataProcessingResult_Delete
	ON RefAirline
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RM_PK
	END
GO
